// Fixture-only exact replay of the production movement gate. Only fixed keys,
// booleans and numeric revision bounds are retained; no identity values/secrets.
pub(super) fn movement_gate_predicates<S:CredentialStore>(c:&Core<S>)->Value{
 let pending=c.pending.lock().unwrap().clone();let ready=pending.as_ref().is_some_and(|p|c.lc1_live_movement_ready(p));
 let control=pending.as_ref().is_some_and(|p|c.validate_current_admission(p).is_ok());
 let mut gates=std::collections::BTreeMap::<&str,bool>::new();
 macro_rules! gate{($key:literal,$value:expr)=>{gates.insert($key,$value);};}
 gate!("pending_present",pending.is_some());gate!("current_control_validation",control);gate!("game_present",c.game.is_some());gate!("desktop_present",c.desktop.is_some());gate!("record_present",c.world.record.is_some());gate!("local_report_present",pending.as_ref().is_some_and(|p|p.observation.is_some()));
 let lifecycle=c.lifecycle.lock().unwrap();let authority=&lifecycle.authority;
 gate!("canonical_admission_present",authority.admission.is_some());
 gate!("admitted_generation_pair_present",c.world.admitted_generations.is_some());
 gate!("lifecycle_generation_matches_record",c.world.admitted_generations.as_ref().zip(c.world.record.as_ref()).is_some_and(|(g,r)|g.lifecycle>0&&g.lifecycle==r.canonical_generation));
 gate!("participant_generation_matches_admission",c.world.admitted_generations.as_ref().zip(authority.admission.as_ref()).is_some_and(|(g,a)|Some(g.participant)==a.generation.filter(|v|*v>0)));
 gate!("generation_pair_ticket_current",c.world.admitted_generations.as_ref().zip(c.game.as_ref()).zip(c.world.record.as_ref()).is_some_and(|((g,game),r)|c.world.coordinator.current(&g.ticket)&&g.ticket.native==game.owner&&g.ticket.world==r.world));
 let snapshot=|gates:&std::collections::BTreeMap<&str,bool>|json!({"production_ready":ready,"gates":gates,"replay_matches_production":gates.values().all(|v|*v)==ready,"boundary":"Core predicate snapshot; not a rejected-socket snapshot"});
 let(Some(p),Some(game),Some(desktop),Some(record),Some(a))=(pending.as_ref(),c.game.as_ref(),c.desktop.as_ref(),c.world.record.as_ref(),authority.admission.as_ref())else{return snapshot(&gates)};
 gate!("canonical_scope_present",a.scope.is_some());gate!("canonical_owner_present",a.owner.is_some());gate!("canonical_report_present",a.current_report.is_some());gate!("canonical_decision_present",a.decision.is_some());
 let(Some(report),Some(scope),Some(owner),Some(current),Some(decision))=(p.observation.as_ref(),a.scope.as_ref(),a.owner.as_ref(),a.current_report.as_ref(),a.decision.as_ref())else{return snapshot(&gates)};
 gate!("game_entered",game.entered);gate!("native_owner_matches_game",p.owner==Some(game.owner));gate!("native_context_matches_game",report.context==game.owner.1);gate!("local_report_unprotected",!report.observation.protected);
 gate!("local_run_matches_record",p.run==record.identity.run);gate!("local_run_epoch_matches_record",p.epoch==record.identity.run_epoch);gate!("local_config_matches_record",p.config==record.identity.config);
 gate!("authority_entered",authority.entered);gate!("service_id_matches",a.service_id.as_deref()==Some(&c.service));gate!("service_epoch_matches",a.service_epoch.as_deref()==Some(&c.epoch));
 gate!("principal_matches_game",scope.principal_id.as_deref()==Some(&game.session.account));gate!("session_id_matches_game",scope.session_id.as_deref()==Some(&game.session.id));gate!("session_epoch_matches_game",scope.session_epoch.as_deref()==Some(&game.session.epoch));gate!("attachment_matches_game",scope.attachment_id.as_deref()==Some(&game.session.attachment));
 gate!("room_matches_record",scope.room_id.as_deref()==Some(&record.identity.room));gate!("run_matches_native",scope.run_id.as_deref()==Some(&p.run));gate!("run_epoch_matches_native",scope.run_epoch.as_deref()==Some(&p.epoch));gate!("config_matches_native",scope.config_revision.map(u64::from)==Some(p.config));gate!("world_matches_record",scope.world_token.as_deref()==Some(record.world.to_string().as_str()));
 gate!("desktop_id_matches_core",owner.desktop_id.as_deref()==Some(&desktop.id));gate!("desktop_epoch_matches_core",owner.desktop_session_epoch.as_deref()==Some(&desktop.epoch));gate!("owner_session_matches_game",owner.game_session_id.as_deref()==Some(&game.session.id));gate!("owner_epoch_matches_game",owner.game_session_epoch.as_deref()==Some(&game.session.epoch));gate!("owner_attachment_matches_game",owner.attachment_id.as_deref()==Some(&game.session.attachment));gate!("owner_instance_matches_native",owner.game_instance_id.as_deref()==Some(uuid::Uuid::from_bytes(game.owner.1).to_string().as_str()));
 gate!("canonical_authorized",decision.authorized==Some(true));gate!("canonical_playing",decision.playing==Some(true));gate!("canonical_nonterminal",decision.terminal!=Some(true));gate!("canonical_unprotected",current.protected==Some(false));gate!("canonical_complete",current.complete==Some(true));gate!("canonical_loaded",current.loaded==Some(true));gate!("canonical_content_valid",current.content_valid==Some(true));gate!("canonical_revision_in_native_range",current.revision.filter(|r|*r>0).map(u64::from).is_some_and(|r|r>=p.invalidated_observation&&r<=report.sequence));
 let mut result=snapshot(&gates);result["revision_bounds"]=json!({"canonical":current.revision,"native":report.sequence,"invalidated_floor":p.invalidated_observation});
 result["generations"]=json!({"record_lifecycle":record.canonical_generation,"canonical_participant":a.generation,"installed_pair":c.world.admitted_generations.as_ref().map(|g|json!({"lifecycle":g.lifecycle,"participant":g.participant}))});
 result["desktop_context"]=json!({"context_present":c.world.ctx.is_some(),"core_identity_matches_context":c.world.ctx.as_ref().is_some_and(|ctx|ctx.desktop.id==desktop.id&&ctx.desktop.epoch==desktop.epoch&&ctx.desktop.account==desktop.account),"core_access_matches_context":c.world.ctx.as_ref().is_some_and(|ctx|ctx.desktop.access.as_str()==desktop.access.as_str()),"canonical_owner_matches_context":c.world.ctx.as_ref().is_some_and(|ctx|owner.desktop_id.as_deref()==Some(&ctx.desktop.id)&&owner.desktop_session_epoch.as_deref()==Some(&ctx.desktop.epoch))});
 result
}
